import{z as l,x as s,o as B,c as d,q as r,j as n,D as e,d as A,s as o,S as t,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"信息中介","description":"","frontmatter":{"title":"信息中介","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/information-intermediaries.md","filePath":"econ/information-intermediaries.md","lastUpdated":1791413859000}'),p={name:"econ/information-intermediaries.md"};function D(m,E,f,u,h,C){const i=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="信息中介" tabindex="-1">信息中介 <a class="header-anchor" href="#信息中介" aria-label="Permalink to &quot;信息中介&quot;">​</a></h1><div class="epigraph"><p>中介卖的是可被许多人同时使用的信号；激励问题是：评级要像验证过的披露，还是像被发行人买来的公共噪声。</p><footer>—— 据 Lizzeri, Information Revelation and Certification Intermediaries, RAND Journal of Economics, 1999；对照评级与认证理论</footer></div><p><a href="/econ/disclosure-theory">上一课</a>的开口人是持有 \\(\\theta\\) 的卖方自己。本课缺口是外包：一个第三方生产公共 \\(y\\)，卖给买方或向发行人收费。不重推揭开的逆向归纳，不把中介写成某家机构的沿革。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>获取课已经说过：公共信号有固定成本时，要么撑起一家生产者，要么没有。认证中介承诺把类型映射成标签。Lizzeri（1999）指出：垄断中介未必充分揭示——它可能把中间类型搅在一起，以抽取认证费，只分开两端。竞争与声誉把标签往更揭示的方向推，但发行人付费（issuer-pays）会把中介的目标从「买方的精度」扭向「发行人的发行价格」。</p><p>缺口是把 \\(y\\) 的生产写成产业，而不是假定天上掉下一则 Morris–Shin 公告。分析师、评级、审计，在本栏都是同一类对象：把私有采集变成公共标签。它们改变 Hellwig 价格里的公共成分，也改变 Glosten–Milgrom 价差里的知情比例。</p><p><span class="marginnote">Ramakrishnan–Thakor、Millon–Thakor 把银行与审计当信息生产者。本课不写银行资本监管；货币银行主干已经有中介的流动性保险，这里只留认证。</span><span class="marginnote">术语翻译：issuer-pays（发行人付费）就是「被评判的人付钱给评判者」的商业模式。就像让考生给阅卷老师发工资——激励方向天然拧着，需要声誉或竞争来纠偏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>中介选择一个信息结构（标签的精细度）和一个收费方。买方付费：接近销售信号的垄断，揭示通常过度或不足取决于能否禁止转卖——信息一旦说出就有公共性，收费难。发行人付费：中介卖的是「好标签」，揭开逻辑部分恢复（差的不来认证），但搅拌与评级购物进入。声誉：未来的认证费依赖今天标签与事后 \\(\\theta\\) 的对齐，约束搅拌，在一次性博弈里消失。</p><p>接到 REE：更精细的公共 \\(y\\) 加深价格揭示，压低私人采集（GS 替代），同时加强协调（Morris–Shin 权重）。中介的社会价值因此不是「信息越多越好」，而是这三股力的净额。</p>',10)),(B(),n(t,null,{default:e(()=>[o(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIX%5B%22%E5%9B%BA%E5%AE%9A%E6%88%90%E6%9C%AC%22%5D%20--%3E%20IND%5B%22%E4%B8%80%E5%AE%B6%E4%B8%AD%E4%BB%8B%E6%88%96%E9%9B%B6%22%5D%0A%20%20IND%20--%3E%20LAB%5B%22%E6%A0%87%E7%AD%BE%E7%B2%BE%E7%BB%86%E5%BA%A6%22%5D%0A%20%20PAY%5B%22%E8%B0%81%E4%BB%98%E8%B4%B9%22%5D%20--%3E%20INC%5B%22%E6%8F%AD%E7%A4%BA%20vs%20%E6%90%85%E6%8B%8C%22%5D%0A%20%20LAB%20--%3E%20Y%5B%22%E5%85%AC%E5%85%B1%20y%22%5D%0A%20%20Y%20--%3E%20GS%5B%22%E5%8E%8B%E4%BD%8E%E7%A7%81%E4%BA%BA%E9%87%87%E9%9B%86%22%5D%0A%20%20Y%20--%3E%20MS%5B%22%E6%8A%AC%E9%AB%98%E5%8D%8F%E8%B0%83%E6%9D%83%E9%87%8D%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"不要把分析师覆盖的截面回归、评级迁移矩阵写进来。那些是测量。本课只钉：标签是被生产出来的公共信号，激励决定它像披露还是像噪声。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"机制是信息的非竞争性与收费冲突。同一则 \\(y\\) 可被所有交易者使用，私人供给不足，中介是一种俱乐部或垄断供给。发行人付费让被评对象变成客户，揭开的「好类型想分开」变成「好类型想买更高标签」，中介若能搅拌则抽租。竞争降低抽租，也可能竞次（为拿业务而抬标签）。声誉把动态租金押在准确性上，是约束而不是消除。",-1)),E[6]||(E[6]=a("p",null,"与柠檬对照：中介若可验证，市场从 Akerlof 搬向 Grossman 揭开；中介若只是有偏的 \\(y\\)，市场多了一则公共噪声，美人竞赛会放大它。",-1)),E[7]||(E[7]=a("p",null,[a("span",{class:"marginnote"},"强制披露与强制评级是替代：前者把阈值推低，后者把中介的需求曲线外移。两者都改变公共与私有的分界，都不自动给出完全揭示。")],-1)),E[8]||(E[8]=a("p",null,[a("span",{class:"marginnote"},"数字实例：信息的固定成本是「生产一次、人人可用」。设生产一则准确标签要 100 万元，市场有 1 万个买方——人均成本 100 元，买得起；市场只有 50 个人——人均 2 万元，没人买。这就是固定成本决定「一家中介或零」的算术。")],-1)),(B(),n(t,null,{default:e(()=>[o(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISSUER%5B%22%E5%8F%91%E8%A1%8C%E4%BA%BA%E4%BB%98%E8%B4%B9%E7%BB%99%E4%B8%AD%E4%BB%8B%22%5D%20--%3E%20GRADE%5B%22%E4%B8%AD%E4%BB%8B%E7%BB%99%E5%87%BA%E6%A0%87%E7%AD%BE%22%5D%0A%20%20GRADE%20--%3E%20SHOP%5B%22%E5%B7%AE%E7%B1%BB%E5%9E%8B%E5%8E%BB%E5%88%AB%E5%AE%B6%E8%B4%AD%E7%89%A9%22%5D%0A%20%20SHOP%20--%3E%20INFL%5B%22%E6%A0%87%E7%AD%BE%E8%A2%AB%E6%8A%AC%E9%AB%98%20%2F%20%E6%90%85%E6%8B%8C%22%5D%0A%20%20INFL%20--%3E%20NOISE%5B%22%E6%A0%87%E7%AD%BE%E4%BF%A1%E6%81%AF%E5%90%AB%E9%87%8F%E4%B8%8B%E9%99%8D%22%5D%0A%20%20NOISE%20--%3E%20REPUT%7B%22%E6%9C%89%E5%A3%B0%E8%AA%89%E7%BA%A6%E6%9D%9F%E5%90%97%3F%22%7D%0A%20%20REPUT%20--%20%22%E6%9C%89%3A%20%E4%BA%8B%E5%90%8E%E5%AF%B9%E4%B8%8D%E4%B8%8A%E6%A0%87%E7%AD%BE%E4%BC%9A%E4%B8%A2%E6%9C%AA%E6%9D%A5%E8%AE%A4%E8%AF%81%E8%B4%B9%22%20--%3E%20DISC%5B%22%E6%A0%87%E7%AD%BE%E8%A2%AB%E6%8B%89%E5%9B%9E%E5%87%86%E7%A1%AE%22%5D%0A%20%20REPUT%20--%20%22%E4%B8%80%E6%AC%A1%E6%80%A7%E5%8D%9A%E5%BC%88%22%20--%3E%20STAY%5B%22%E5%99%AA%E5%A3%B0%E5%9B%BA%E5%8C%96%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[9]||(E[9]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是微观结构里的「信息卖家把信号卖给高频」。速度与独占数据是协议层的产权。下一课把本单元收束：信息均衡给出价格应当反映什么、流动性成本从何来；这些数字如何出现在屏幕上，仍交给簿。资产定价后半课程要从无套利写起，需要这块接口，以免把 \\(\\lambda\\) 误当成 SDF。</p><p>后课默认：信息中介生产公共标签；收费方与竞争决定揭示还是搅拌。\\(y\\) 同时进入采集替代与协调权重。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>固定成本使公共信号由中介生产；垄断不必充分揭示。</li><li>发行人付费引入搅拌与购物；声誉是动态约束。</li><li>中介的 \\(y\\) 改变 REE 揭示、价差与美人竞赛权重。</li><li>出处：Lizzeri, <em>RAND</em> 1999；对照认证与评级的激励文献。</li></ul>',5))])}const P=l(p,[["render",D]]);export{T as __pageData,P as default};
